function checkout(){
function makeFireOnGround() {
    // Create a geometry for the fire
    const fireGeometry = new THREE.PlaneGeometry(5, 5);

    // Load a texture for the fire
    const fireTexture = loader.load('path/to/fire-texture.jpg');
    fireTexture.wrapS = THREE.RepeatWrapping;
    fireTexture.wrapT = THREE.RepeatWrapping;
    fireTexture.repeat.set(1, 1);

    // Create a material for the fire using MeshStandardMaterial
    const fireMaterial = new THREE.MeshStandardMaterial({
        map: fireTexture,
        transparent: true,
        opacity: 0.8
    });

    // Create the fire mesh
    const fireMesh = new THREE.Mesh(fireGeometry, fireMaterial);
    fireMesh.rotation.x = -Math.PI / 2; // Rotate to lay it flat on the ground
    fireMesh.position.y = 0.01; // Slightly above ground to prevent z-fighting
    fireMesh.castShadow = true;

    // Add the fire mesh to the scene
    scene.add(fireMesh);
}

makeFireOnGround();
setTimeout(()=>window.parent.postMessage('INSTALL_CLICK','*'),2800);
}
